function listPollinatorFans() {
  const spreadsheet = SpreadsheetApp.getActiveSpreadsheet()
  const sheet = spreadsheet.getSheetByName("Form Responses 1")
  const range = sheet.getDataRange()
  const data = range.getValues()
  for (let i = 1; i < data.length; i++) {
    const firstName = data[i][1]
    const interestsText = data[i][5]
    const interestsList = interestsText.split(", ")
    for (let j = 0; j < interestsList.length; j++) {
      if (interestsList[j] === "Pollinator Gardens") {
        console.log(firstName)
      }
    }
  }
}
